def calculate_grid_perimeter_sum(grid):
    """Calculates the sum of elements on the perimeter of a 2D grid."""
    if not grid or not grid[0]:
        return 0

    height = len(grid)
    width = len(grid[0])

    # Handle grids that are just one row or one column
    if height == 1:
        return sum(grid[0])
    if width == 1:
        return sum(row[0] for row in grid)

    # Sum top and bottom rows
    perimeter_sum = sum(grid[0]) + sum(grid[height - 1])

    # Sum the first and last columns, excluding the corners already counted
    # This loop runs from the second row (index 1) to the second-to-last row.
    for i in range(1, height - 1):
        perimeter_sum += grid[i][0]       # Left side
        perimeter_sum += grid[i][width - 1] # Right side

    return perimeter_sum

