def dequeue_prefix_from_string(queue_str, n):
    """Dequeues the first n items from a comma-separated string queue."""
    if n <= 0:
        return ""

    commas_found = 0
    end_index = -1
    for i, char in enumerate(queue_str):
        if char == ',':
            commas_found += 1
            if commas_found == n:
                end_index = i
                break

    # If n-th comma was not found, n >= total items, so return the whole string
    if end_index == -1:
        return queue_str

    # Slice up to, but not including, the n-th comma
    return queue_str[:end_index]

