def find_longest_palindromic_prefix(s: str) -> str:
    if not s:
        return ""
    # Iterate from the longest possible prefix length down to 1
    for length in range(len(s), 0, -1):
        # Check if the prefix of this length is a palindrome using two pointers
        is_palindrome = True
        left, right = 0, length - 1
        while left < right:
            if s[left] != s[right]:
                is_palindrome = False
                break
            left += 1
            right -= 1

        # If it is a palindrome, we've found the longest one, so we return it
        if is_palindrome:
            return s[:length]

    return ""

